/**
 * rsync success, INCLUDING the two partial-success exit codes that our own
 * `-A -X` flags provoke. With ACLs (`-A`) and xattrs (`-X`) requested, rsync
 * exits **23** ("partial transfer due to error") whenever the destination
 * filesystem or SELinux rejects an ACL/xattr the source carried, and **24**
 * ("some source files vanished") when a live source deletes a file mid-copy.
 * In BOTH cases the FILE DATA still transferred — only an attribute or a since-
 * deleted file was skipped — so treating them as a failed copy would declare a
 * fully-populated directory uncopied and, worse, let the empty-volume guards
 * fire on data that is actually present. Only ever apply this to `rsyncPull`
 * results — never to plain `sh` calls whose non-zero codes mean what they say.
 */
function rsyncOk(code: number): boolean {
  return code === 0 || code === 23 || code === 24;
}
/** True only for the tolerated-but-imperfect rsync codes (worth a note). */
function rsyncPartial(code: number): boolean {
  return code === 23 || code === 24;
}
