if (ce.args) await report(75, "Starting containers…", `  ${dir}: using ${ce.envFile} for its settings.`);
// Parse the MERGED compose config ONCE and reuse it for two pre-flight
// decisions below:
//   #4 buildImages — images that belong to a service WITH a `build:` context.
//      `up -d` can build these locally from the copied build dir, so a failed
//      image TRANSFER must NOT hard-block the project; only a non-build image
//      that can't be pulled/transferred is a real blocker.
//   #6 effectiveNames — the authoritative merged container_names. A raw grep
//      across every -f file double-counts a name an override redefines and can
//      falsely skip an unrelated project; `config` gives the real merged names.
const buildImages = new Set<string>();
const effectiveNames: string[] = [];
try {
  const cfgRaw = clean((await sh(conn, `sh -c 'cd ${dir} && ${composeCmd} ${ce.fileArg}${ce.args}${projArg}config --format json 2>/dev/null'`)).stdout, 4_000_000);
  if (cfgRaw) {
    const parsed = JSON.parse(cfgRaw) as unknown;
    const services = (parsed && typeof parsed === "object") ? (parsed as Record<string, unknown>).services : null;
    if (services && typeof services === "object") {
      // Same project the `-p`/basename default gives, so synthesized build
      // image names (`<project>-<service>`) line up with `config --images`.
      const composeProject = proj || (dir.replace(/\/+$/, "").split("/").pop() || "").toLowerCase().replace(/[^a-z0-9_-]/g, "");
