        const def = (defRaw && typeof defRaw === "object") ? (defRaw as Record<string, unknown>) : {};
        const cn = typeof def.container_name === "string" ? def.container_name.trim() : "";
        if (cn) effectiveNames.push(cn);
        if (def.build) {
          const img = typeof def.image === "string" ? def.image.trim() : "";
          if (img) buildImages.add(img);
          // A build service with no explicit `image:` gets a synthesized name
          // — compose v2 uses `<project>-<service>`, a v1 source `_`. Cover both.
          if (composeProject && svc) { buildImages.add(`${composeProject}-${svc}`); buildImages.add(`${composeProject}_${svc}`); }
