const nft = await sh(conn, `command -v nft >/dev/null 2>&1 && nft list ruleset 2>/dev/null | grep -iE 'hook input|dport' | head -n 40`);
if (/policy\s+(drop|reject)/i.test(nft.stdout)) {
  // #8: this probe runs on THE TARGET, so the ruleset is this (new) server's own.
  // Optional accept-check: if the input chain already accepts BOTH web ports, the
  // drop policy is not blocking them — stay silent rather than raise a false alarm.
  const portAccepted = (p: string) => new RegExp(`dport[^\\n]*\\b${p}\\b[^\\n]*accept`, "i").test(nft.stdout);
  if (!(portAccepted("80") && portAccepted("443"))) {
    return {
      kind: "nftables",
      detail:
        "this (new) server has an nftables ruleset with a drop/reject input policy that leaves the web ports closed — open the web ports (and your app's own ports) so the site can answer, e.g.: nft add rule inet filter input tcp dport { 80, 443 } accept (adjust the table/chain to match `nft list ruleset`)",
    };
  }
}

