// 10f. Firewall — an open port 80/443 is the last thing between DNS and a
// working site.
{
  const fw = await openWebPorts(conn);
  push({
    step: "Firewall",
    status: fw.kind === "iptables" || fw.kind === "nftables" ? "copied" : "running",
    detail: fw.detail,
  });
}

// 10f-bis. #9: honest-refuse for the SOURCE's own restrictive nftables policy.
// detectSource sets `nftablesDropPolicy` on the ScanResult, but that field is
// never carried into Migration.items.scan (the persistence layer) and so never
// reached this engine — the intended "we did NOT copy your firewall" step went
// unrendered. Re-probe it LIVE here (read-only, quote-safe: no single quotes for
// the source SSH channel) and name it, exactly like the alt-proxy / non-systemd
// honest steps above. The web ports are already handled by openWebPorts on THIS
// server; this only warns about the OTHER (app-specific) ports a copied firewall
// would have carried. Best-effort — a probe failure must never fail the run.
{
  const nftProbe = await sh(
    conn,
    onSource(
      "if command -v nft >/dev/null 2>&1; then fwmgr=0; " +
        "command -v ufw >/dev/null 2>&1 && ufw status 2>/dev/null | head -n1 | grep -qi \"Status: active\" && fwmgr=1; " +
        "command -v firewall-cmd >/dev/null 2>&1 && firewall-cmd --state 2>/dev/null | grep -qi running && fwmgr=1; " +
        "if [ \"$fwmgr\" = 0 ]; then nft list ruleset 2>/dev/null | grep -iE \"hook input\" | grep -qiE \"policy[[:space:]]+(drop|reject)\" && echo NFTDROP; fi; fi"
    )
  ).catch(() => ({ code: 1, stdout: "", stderr: "" }));
  if (/NFTDROP/.test(clean(nftProbe.stdout, 200))) {
    push({
      step: "Old server's nftables firewall was NOT copied",
      status: "copied",
      detail:
        "the old server ran an nftables ruleset with a drop/reject input policy — it was NOT copied to this server (blindly replaying a firewall ruleset is unsafe). This server's web ports 80/443 were opened automatically; if your apps also listen on OTHER ports, open those too, e.g.: nft add rule inet filter input tcp dport { 80, 443 } accept (adjust the table/chain to match `nft list ruleset`).",
    });
    await report(90, "Re-enabling services…", "  The old server had a restrictive nftables firewall — named for you to reproduce (only 80/443 were opened here automatically).");
  }
}

